"""The gate refuses to run on libraries other than CI's (#44).

Lock lines here are copied in shape from `requirements/ci.txt` as
`uv pip compile --universal --generate-hashes` writes it, not built from
`lock_drift`'s own pattern.
"""

from __future__ import annotations

import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "scripts"))

import lock_drift  # noqa: E402

LOCK = """\
# This file was autogenerated by uv via the following command:
#    uv pip compile pyproject.toml --extra dev --universal --generate-hashes -o requirements/ci.txt
annotated-types==0.8.0 \\
    --hash=sha256:13b2beaad985e05e2d6407ee4c4f35590b11f8d693a258a561055cac8f64cab7
    # via pydantic
Anthropic==1.7.0 \\
    --hash=sha256:0ab1b04668606ba1ae93f6d9e8dcc2e0c4f0debebd4eea4773a3a595f0836db1
    # via policyforge (pyproject.toml)
pywin32==312 ; sys_platform == 'win32' \\
    --hash=sha256:aaaa
httpx2-jsfetch==1.0 ; sys_platform == 'emscripten' \\
    --hash=sha256:bbbb
pydantic_core==2.46.5 \\
    --hash=sha256:cccc
"""

LINUX = {"sys_platform": "linux"}


def test_every_pin_shape_in_the_lock_is_read():
    got = lock_drift.pins(LOCK)
    assert got == {
        "annotated-types": ("0.8.0", None),
        "anthropic": ("1.7.0", None),
        "pywin32": ("312", "sys_platform == 'win32'"),
        "httpx2-jsfetch": ("1.0", "sys_platform == 'emscripten'"),
        "pydantic-core": ("2.46.5", None),
    }


def test_the_real_lock_is_read_whole():
    """Extent, by a second instrument: every line that starts a requirement
    (a letter at column 0) and pins with `==`."""
    text = (ROOT / "requirements" / "ci.txt").read_text(encoding="utf-8")
    expected = sum(1 for ln in text.splitlines() if ln[:1].isalpha() and "==" in ln)
    assert expected > 50
    assert len(lock_drift.pins(text)) == expected


def _have(**overrides):
    have = {
        "annotated-types": "0.8.0",
        "anthropic": "1.7.0",
        "pydantic-core": "2.46.5",
        "policyforge": "1.7.0",
    }
    have.update(overrides)
    return {k: v for k, v in have.items() if v is not None}


def test_a_matching_environment_passes():
    """What it must ALLOW: the lock installed, plus the project itself."""
    report = lock_drift.classify(lock_drift.pins(LOCK), _have(), LINUX)
    assert report.ok
    assert report.same == ["annotated-types", "anthropic", "pydantic-core"]
    assert report.unlocked == ["policyforge"]


def test_a_moved_pin_is_refused():
    report = lock_drift.classify(lock_drift.pins(LOCK), _have(anthropic="0.125.0"), LINUX)
    assert not report.ok
    assert report.different == {"anthropic": ("1.7.0", "0.125.0")}


def test_a_missing_package_is_refused():
    report = lock_drift.classify(lock_drift.pins(LOCK), _have(**{"pydantic-core": None}), LINUX)
    assert not report.ok
    assert report.missing == {"pydantic-core": "2.46.5"}


def test_a_pin_for_another_platform_is_not_required():
    report = lock_drift.classify(lock_drift.pins(LOCK), _have(), LINUX)
    assert report.not_here == ["httpx2-jsfetch", "pywin32"]


def test_a_pin_for_this_platform_is_required():
    report = lock_drift.classify(lock_drift.pins(LOCK), _have(), {"sys_platform": "win32"})
    assert report.missing == {"pywin32": "312"}
    assert report.not_here == ["httpx2-jsfetch"]


class _Dist:
    def __init__(self, name, version):
        self.metadata = {"Name": name}
        self.version = version


def test_a_name_installed_twice_is_read_as_the_first_on_the_path():
    """ba on #46: resolution takes the FIRST distribution of a name, so a
    stale copy found first must be what is compared, not a good one behind it."""
    have = lock_drift.installed([_Dist("Click", "0.0.1"), _Dist("click", "8.5.0")])
    assert have == {"click": "0.0.1"}
    locked = {"click": ("8.5.0", None)}
    report = lock_drift.classify(locked, have, LINUX)
    assert report.different == {"click": ("8.5.0", "0.0.1")}


def test_installed_reads_this_environment_by_default():
    have = lock_drift.installed()
    assert have.get("packaging")  # in the lock, and imported by lock_drift itself


def test_a_lock_with_no_pins_is_nothing_to_compare_not_a_pass():
    with pytest.raises(lock_drift.NothingToCompare, match="ZERO pins"):
        lock_drift.classify(lock_drift.pins("# only comments\n"), _have(), LINUX)


def _semgrep_says(monkeypatch, stdout):
    def fake(cmd, **kwargs):
        return subprocess.CompletedProcess(cmd, 0, stdout=stdout, stderr="")

    monkeypatch.setattr(lock_drift.subprocess, "run", fake)


def test_semgreps_version_is_read_under_its_update_notice(monkeypatch):
    _semgrep_says(monkeypatch, "A new version of Semgrep is available.\n1.174.0\n")
    assert lock_drift.semgrep_version("semgrep") == "1.174.0"


def test_an_unreadable_semgrep_version_is_refused(monkeypatch):
    _semgrep_says(monkeypatch, "")
    with pytest.raises(lock_drift.NothingToCompare, match="version"):
        lock_drift.semgrep_version("semgrep")


# --- through main(), the path check.py takes ---------------------------------


@pytest.fixture
def world(tmp_path, monkeypatch):
    ci = tmp_path / "ci.txt"
    ci.write_text(LOCK, encoding="utf-8")
    sg = tmp_path / "semgrep.txt"
    sg.write_text("semgrep==1.177.0 \\\n    --hash=sha256:dddd\n", encoding="utf-8")
    monkeypatch.setattr(lock_drift, "CI_LOCK", ci)
    monkeypatch.setattr(lock_drift, "SEMGREP_LOCK", sg)
    monkeypatch.setattr(lock_drift, "installed", _have)
    real_classify = lock_drift.classify
    monkeypatch.setattr(
        lock_drift, "classify", lambda locked, have: real_classify(locked, have, LINUX)
    )
    return ci


def test_main_passes_a_matching_environment(world, capsys):
    assert lock_drift.main([]) == 0
    out = capsys.readouterr().out
    assert "3 pin(s) for this platform: 3 same, 0 DIFFERENT, 0 MISSING" in out


def test_main_names_each_drift_and_exits_1(world, monkeypatch, capsys):
    monkeypatch.setattr(
        lock_drift, "installed", lambda: _have(anthropic="0.125.0", **{"pydantic-core": None})
    )
    assert lock_drift.main([]) == 1
    out = capsys.readouterr().out
    assert "DIFFERENT  anthropic  lock 1.7.0, installed 0.125.0" in out
    assert "MISSING    pydantic-core  lock 2.46.5" in out


def test_main_refuses_a_semgrep_other_than_the_locked_one(world, monkeypatch, capsys):
    _semgrep_says(monkeypatch, "1.174.0\n")
    assert lock_drift.main(["--semgrep", "semgrep"]) == 1
    assert "semgrep: lock 1.177.0, the gate's 1.174.0: DIFFERENT" in capsys.readouterr().out


def test_main_passes_the_locked_semgrep(world, monkeypatch, capsys):
    _semgrep_says(monkeypatch, "1.177.0\n")
    assert lock_drift.main(["--semgrep", "semgrep"]) == 0


def test_main_exits_2_on_an_empty_lock(world, capsys):
    world.write_text("# nothing pinned\n", encoding="utf-8")
    assert lock_drift.main([]) == 2
    assert "ZERO pins" in capsys.readouterr().err


def test_without_packaging_it_exits_2_never_1():
    """Found live: an environment not built from the lock lacked
    `packaging`, and the import error exited 1, which reads as drift."""
    code = (
        "import sys, runpy; sys.modules['packaging'] = None; "
        f"sys.argv = ['lock_drift']; runpy.run_path({str(ROOT / 'scripts' / 'lock_drift.py')!r})"
    )
    r = subprocess.run(
        [sys.executable, "-c", code],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        check=False,
    )
    assert r.returncode == 2, (r.returncode, r.stderr)
    assert "`packaging` is not installed" in r.stderr


def _check_module():
    import importlib.util

    spec = importlib.util.spec_from_file_location("check_gate", ROOT / "scripts" / "check.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def test_a_foreign_tool_first_on_path_is_not_the_one_the_gate_runs(tmp_path):
    """9b on #46: lock_drift measures this interpreter, so the gate must run
    this interpreter's tools. A fake `ruff` (a copy of Python, which answers
    `--version` as "Python 3.x") is put first on PATH."""
    import os
    import shutil

    name = "ruff.exe" if os.name == "nt" else "ruff"
    # The base interpreter: a venv's python.exe is a launcher that needs its
    # pyvenv.cfg beside it, so a copy of it would not run at all.
    shutil.copy(getattr(sys, "_base_executable", sys.executable), tmp_path / name)
    env = {**os.environ, "PATH": f"{tmp_path}{os.pathsep}{os.environ.get('PATH', '')}"}
    # The name is resolved INSIDE a child whose own PATH has the fake first,
    # as it is inside check.py. On Windows a bare name is looked up on the
    # CALLING process's PATH, so passing `env` to one subprocess.run would
    # resolve it on this test's PATH instead and prove nothing.
    probe = (
        "import subprocess, sys; r = subprocess.run(sys.argv[1:], capture_output=True, "
        "text=True, encoding='utf-8', errors='replace'); print(r.stdout + r.stderr)"
    )

    def version(cmd):
        r = subprocess.run(
            [sys.executable, "-c", probe, *cmd],
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            env=env,
            check=False,
        )
        return (r.stdout + r.stderr).strip()

    # Control arm: the fake really does shadow a bare name.
    assert version(["ruff", "--version"]).startswith("Python")
    # What the gate runs is this interpreter's ruff, whatever PATH says.
    assert version(_check_module()._tool("ruff", "--version")).startswith("ruff ")


def test_no_python_tool_in_the_gate_is_run_by_bare_name():
    """Every command check.py hands to `run()` is `_tool(...)` or starts
    with a binary that is not a Python package from the lock."""
    import ast

    tree = ast.parse((ROOT / "scripts" / "check.py").read_text(encoding="utf-8"))
    not_python = {"git", "gitleaks"}
    bare = []
    for node in ast.walk(tree):
        if not (isinstance(node, ast.Call) and getattr(node.func, "id", "") == "run"):
            continue
        cmd = node.args[1] if len(node.args) > 1 else None
        if isinstance(cmd, ast.Call) and getattr(cmd.func, "id", "") == "_tool":
            continue
        first = cmd.elts[0] if isinstance(cmd, ast.List) and cmd.elts else None
        if isinstance(first, ast.Attribute) and ast.unparse(first) == "sys.executable":
            continue
        if isinstance(first, ast.Name):  # a resolved path, e.g. find_semgrep()'s
            continue
        if isinstance(first, ast.Constant) and first.value in not_python:
            continue
        bare.append(ast.unparse(cmd) if cmd is not None else "?")
    assert not bare, bare


def test_check_runs_the_drift_check_first():
    """First, so every other result says which libraries it measured."""
    source = (ROOT / "scripts" / "check.py").read_text(encoding="utf-8")
    body = source[source.index("results: dict[str, bool | None] = {") :]
    first = body.index('"', body.index("{"))
    assert body[first:].startswith('"environment matches CI\'s locks"')


def test_a_worktree_finds_semgrep_in_the_main_checkouts_tools(tmp_path, monkeypatch):
    """#46's re-sync moves semgrep out of the shared venv into the shared
    clone's .tools/semgrep. Every session gates in its own worktree, whose
    REPO_ROOT has no .tools/, so without looking in the main checkout each
    gate would skip semgrep: an unacknowledged skip, exit 1, for everyone."""
    import os
    import shutil

    main = tmp_path / "main"
    main.mkdir()
    subprocess.run(["git", "init", "-q", "-b", "main", str(main)], check=True)
    subprocess.run(
        [
            "git",
            "-C",
            str(main),
            "-c",
            "user.name=t",
            "-c",
            "user.email=t@invalid",
            "commit",
            "-q",
            "--allow-empty",
            "-m",
            "root",
        ],
        check=True,
    )
    tree = tmp_path / "wt"
    subprocess.run(
        ["git", "-C", str(main), "worktree", "add", "-q", "--detach", str(tree)], check=True
    )
    scripts = "Scripts" if os.name == "nt" else "bin"
    exe = main / ".tools" / "semgrep" / scripts / ("semgrep.exe" if os.name == "nt" else "semgrep")
    exe.parent.mkdir(parents=True)
    shutil.copy(sys.executable, exe)

    check = _check_module()
    monkeypatch.setattr(check, "REPO_ROOT", tree)
    real_which = shutil.which  # captured BEFORE patching: the fake must not call itself

    def which(name, path=None):
        return real_which(name, path=path) if path is not None else None  # nothing on PATH

    monkeypatch.setattr(check.shutil, "which", which)
    found = check.find_semgrep()
    assert found and Path(found).resolve() == exe.resolve(), found
